# LOTO version of PGSS_YOLO11/train_pgss.py (GitHub b2f792f, SHA-256 8d895af685846654...), generated by
# make_loto_training_scripts.py. Changes vs R1: see patches/PGSS_YOLO11.diff. Launch through
# run_step1_training.sh (it sets LOTO_FOLD, LOTO_SEED, LOTO_DATA_ROOT, LOTO_OUT_ROOT).
"""
Train genuine PGSS-YOLO11s (custom YAML: GLSA + AWFF + DEConv wired into the graph).
Pretrained yolo11s-seg backbone transferred via .load(); trained on the leakage-corrected
clean split, img 512, batch 8, AdamW lr 5e-4, cosine LR + 3-epoch warmup, mosaic+mixup+
label-smoothing (matching the PGSS notebook's settings).

Early stopping: see YOLO11seg/train_yolo11_seg.py for the full rationale -- Ultralytics'
own `patience` early-stops on its internal "fitness" (box+mask mAP composite), not Dice.
Native patience is disabled here and a custom callback drives the actual stop decision from
a genuine per-epoch validation Dice (derived as F1 = 2PR/(P+R) from the mask precision/
recall Ultralytics already computes; F1 on binary masks is exactly the Dice coefficient),
kept consistent with the other six models in this project.
"""
import json
import os
import shutil
import sys
import time

import torch

BASE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, BASE)
import pgss_modules  # noqa: F401  (registers GLSA/AWFF/DEConv with Ultralytics)
import ultralytics
from ultralytics import YOLO

sys.path.insert(0, os.path.abspath(os.path.join(BASE, "..", "..")))  # loto_retraining/
import loto_common as LC  # noqa: E402
CFG = LC.run_config("PGSS_YOLO11")
DATA = CFG["yolo_data"]        # <loto>/<fold>/rebuilt/final_yolo/data.yaml
DEVICE = 0 if torch.cuda.is_available() else "cpu"

SEED = CFG["seed"]
MAX_EPOCHS = CFG["max_epochs"]   # as R1: at most 100 epochs
PATIENCE = CFG["patience"]       # as R1: 15 epochs without improvement (now of the shared Dice)
RUN_DIR = CFG["save_dir"]        # <LOTO_OUT_ROOT>/<fold>/seed<seed>/PGSS_YOLO11


def make_dice_early_stopper(patience=PATIENCE):
    """Returns (on_train_epoch_start, on_fit_epoch_end) callbacks that together
    time each epoch and implement Dice-monitored early stopping via trainer.stop."""
    state = {"best_dice": -1.0, "wait": 0, "history": [], "epoch_start": None}

    def on_train_epoch_start(trainer):
        state["epoch_start"] = time.time()

    def on_fit_epoch_end(trainer):
        metrics = trainer.metrics or {}
        p = next((v for k, v in metrics.items() if "precision(M)" in k), None)
        r = next((v for k, v in metrics.items() if "recall(M)" in k), None)
        if p is None or r is None:
            print(f"[dice-early-stop] WARNING: no mask precision/recall found in "
                  f"trainer.metrics (keys={list(metrics.keys())}); skipping this epoch's check.")
            dice = float("nan")
        else:
            dice = 2 * p * r / (p + r + 1e-9)

        epoch_time = (time.time() - state["epoch_start"]) if state["epoch_start"] else None
        state["history"].append({"epoch": trainer.epoch + 1, "val_dice": dice, "epoch_time_sec": epoch_time})
        with open(os.path.join(trainer.save_dir, "dice_early_stop_log.json"), "w") as f:
            json.dump(state["history"], f, indent=2)

        if dice == dice and dice > state["best_dice"]:  # dice==dice is False for NaN
            state["best_dice"] = dice
            state["wait"] = 0
            best_dice_path = os.path.join(trainer.save_dir, "weights", "best_dice.pt")
            if os.path.exists(trainer.last):
                shutil.copy2(trainer.last, best_dice_path)
            print(f"[dice-early-stop] epoch {trainer.epoch + 1}: new best val Dice {dice:.4f} -> {best_dice_path}")
        else:
            state["wait"] += 1
            print(f"[dice-early-stop] epoch {trainer.epoch + 1}: val Dice {dice:.4f} "
                  f"(best {state['best_dice']:.4f}, no improvement {state['wait']}/{patience})")

        if state["wait"] >= patience:
            print(f"[dice-early-stop] stopping: no val-Dice improvement in {patience} epochs "
                  f"(best {state['best_dice']:.4f}).")
            trainer.stop = True

    return on_train_epoch_start, on_fit_epoch_end


def main():
    print("Device:", DEVICE, torch.cuda.get_device_name(0) if torch.cuda.is_available() else "")

    run_dir = RUN_DIR
    os.makedirs(run_dir, exist_ok=True)

    # Build genuine PGSS architecture, then transfer the pretrained yolo11s-seg backbone.
    model = YOLO(os.path.join(BASE, "yolo11s-pgss-seg.yaml"))
    model.load("yolo11s-seg.pt")
    print("PGSS-YOLO11s built + pretrained backbone transferred.")

    run_meta = {
        "seed": SEED,
        "device": str(DEVICE),
        "gpu_name": torch.cuda.get_device_name(0) if torch.cuda.is_available() else None,
        "package_versions": {
            "python": sys.version.split()[0],
            "torch": torch.__version__,
            "ultralytics": ultralytics.__version__,
            "cuda": torch.version.cuda,
        },
        "total_parameters": sum(p.numel() for p in model.model.parameters()),
        "trainable_parameters": sum(p.numel() for p in model.model.parameters() if p.requires_grad),
    }
    json.dump(run_meta, open(os.path.join(run_dir, "run_metadata.json"), "w"), indent=2)

    # LOTO: replaces the R1 Dice early-stopper; same rule (PATIENCE), scored with the shared Dice
    on_epoch_start, on_epoch_end, SELECTOR = LC.yolo_selection_callbacks(
        os.path.join(CFG["data_root"], "valid"), run_dir, DEVICE, "PGSS_YOLO11", patience=PATIENCE)
    model.add_callback("on_train_epoch_start", on_epoch_start)
    model.add_callback("on_fit_epoch_end", on_epoch_end)

    model.train(
        data=DATA,
        epochs=MAX_EPOCHS,
        imgsz=512,
        batch=8,
        lr0=5e-4,
        optimizer="AdamW",
        seed=SEED,
        cos_lr=True,
        warmup_epochs=3,
        warmup_momentum=0.8,
        warmup_bias_lr=0.1,
        patience=100000,  # Ultralytics' own fitness-based early stop, effectively disabled --
                          # the callback above drives the actual (Dice-monitored) stop decision
        device=DEVICE,
        project=os.path.dirname(run_dir),
        name=os.path.basename(run_dir),
        workers=4,
        verbose=True,
        plots=True,
        exist_ok=True,
        mosaic=1.0,
        mixup=0.1,
        label_smoothing=0.1,
    )
    SELECTOR.finalize(SELECTOR.n_epochs, os.path.join(run_dir, "weights", "best_unified.pt"))
    print("Training done. Run dir:", run_dir)
    print("Checkpoint for testing: weights/best_unified.pt (uniform criterion); Ultralytics best.pt "
          "(native fitness) is not used.")


if __name__ == "__main__":
    main()
